'use strict';
const {templates,detect,parseBudget,parseLevel,planFor}=CircuitGuide;
const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+n.toLocaleString('en-IN');
const welcome='Hi! I’m CircuitGuide. Tell me what you’d like to build.\n\nThis demo can plan automatic plant watering, room temperature/humidity monitoring, or a low-voltage night light. I’ll ask about your budget and experience next.';
function fresh(){return{id:crypto.randomUUID(),key:null,budget:null,level:null,stage:'idea',messages:[{role:'assistant',text:typeof liveAI!=='undefined'&&liveAI?'Hi! I’m CircuitGuide, powered by Groq. What electronics project would you like to build? Tell me your goal, budget in INR and experience level.':welcome}],date:new Date().toISOString()};}
let liveAI=false,busy=false,requestController=null,loginForAI=false;
let authAvailable=false;
let account=null,authMode='login',authGeneration=0,saveQueue=Promise.resolve();
const savedVersions=new Map();
let current=fresh(),history=[],activeTab='components',toastTimer;
function valid(c){return c&&typeof c.id==='string'&&['idea','budget','level','complete'].includes(c.stage)&&Array.isArray(c.messages)&&c.messages.every(m=>['user','assistant'].includes(m.role)&&typeof m.text==='string')&&(!c.key||c.key==='ai'||Object.hasOwn(templates,c.key))&&(c.budget===null||Number.isFinite(c.budget))&&(c.level===null||['Beginner','Intermediate'].includes(c.level));}
try{const data=JSON.parse(localStorage.getItem('circuitguide-v1'));if(valid(data?.current))current=data.current;if(Array.isArray(data?.history))history=data.history.filter(valid);}catch{}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function persist(){
 if(current.key){const index=history.findIndex(x=>x.id===current.id),copy=JSON.parse(JSON.stringify(current));if(index>=0)history[index]=copy;else history.unshift(copy);history=history.slice(0,account?100:20);}
 if(account){if(current.key)saveProject(current);return;}
 try{localStorage.setItem('circuitguide-v1',JSON.stringify({current,history}));}catch{toast('Browser storage is unavailable. Download your plan to keep it.');}
}
function saveProject(project){
 const data=JSON.stringify({...project,messages:project.messages.slice(-200)}),id=project.id,generation=authGeneration;
 if(savedVersions.get(id)===data)return;savedVersions.set(id,data);
 saveQueue=saveQueue.then(async()=>{if(generation!==authGeneration)return;await api('/api/projects',{method:'PUT',body:data});}).catch(error=>{if(generation===authGeneration){savedVersions.delete(id);toast('Project not saved: '+error.message);}});
}
async function api(url,options={}){const response=await fetch(url,{...options,credentials:'same-origin',headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw new Error(data.error==='Method not allowed.'||data.error==='Not found.'?'Restart the server with Ctrl+C, then npm start, and refresh the page.':data.error||'Request failed.');return data;}
function accountUI(){$('accountButton').textContent=account?'Log out':'Log in / Sign up';document.querySelector('.profile>div').firstChild.textContent=account?account.name:'Electronics workspace';document.querySelector('.profile small').textContent=account?'Account projects · SQLite':'Guest · saved in this browser';}
async function loadAccount(user){cancelRequest();authGeneration++;savedVersions.clear();const result=await api('/api/projects');account=user;history=result.projects.filter(valid);for(const p of history)savedVersions.set(p.id,JSON.stringify({...p,messages:p.messages.slice(-200)}));current=history[0]?JSON.parse(JSON.stringify(history[0])):fresh();activeTab='components';accountUI();render();}
function loadGuest(){account=null;history=[];current=fresh();try{const data=JSON.parse(localStorage.getItem('circuitguide-v1'));if(valid(data?.current))current=data.current;if(Array.isArray(data?.history))history=data.history.filter(valid);}catch{}accountUI();render();}
function authView(){const signup=authMode==='register';$('authTitle').textContent=signup?'Make room for your ideas.':'Welcome back.';$('authDescription').textContent=signup?'Create an account to keep your projects together.':'Log in to save your projects to your account.';$('nameLabel').hidden=!signup;$('authName').required=signup;$('authPassword').autocomplete=signup?'new-password':'current-password';$('authSubmit').textContent=signup?'Create account':'Log in';$('authSwitch').textContent=signup?'Already have an account? Log in':'New here? Create an account';$('authError').textContent='';}
async function initAccount(){if(location.protocol==='file:')return;try{const {user}=await api('/api/auth/me');authAvailable=true;if(user)await loadAccount(user);else accountUI();}catch{accountUI();}}
function add(role,text){current.messages.push({role,text});}
function render(){persist();$('history').innerHTML=history.length?history.map(c=>`<button class="history-item ${c.id===current.id?'active':''}" data-history="${esc(c.id)}">${esc((c.aiPlan?.title||templates[c.key]?.title||'Custom electronics project'))}<span>${c.stage==='complete'?'Plan ready':'In progress'} ${c.budget?'· '+money(c.budget):''}</span></button>`).join(''):'<p class="history-empty">Your project conversations will appear here.</p>';
$('messages').innerHTML=current.messages.map(m=>`<div class="message ${m.role}"><span class="message-avatar">${m.role==='user'?'YOU':'⌘'}</span><div><div class="message-label">${m.role==='user'?'YOU':'CIRCUITGUIDE'}</div><div class="bubble">${esc(m.text)}</div></div></div>`).join('');$('messages').scrollTop=$('messages').scrollHeight;
$('stageLabel').textContent={idea:'01 / YOUR IDEA',budget:'02 / YOUR BUDGET',level:'03 / EXPERIENCE',complete:'04 / PLAN READY'}[current.stage];
const options=current.stage==='budget'?['₹1,000','₹1,500','₹2,000']:current.stage==='level'?['Beginner','Intermediate']:current.stage==='complete'?['Change budget','Change experience']:[];
$('quickReplies').innerHTML=options.map(v=>`<button data-reply="${esc(v)}">${v}</button>`).join('');$('messageInput').placeholder={idea:'What would you like to make?',budget:'Your budget in INR, e.g. ₹1,500…',level:'Beginner or intermediate?',complete:'Ask for components, steps, references, or change budget…'}[current.stage];renderPlan();}
function demoRespond(input){const text=input.trim();if(!text)return;add('user',text);
if(current.stage==='idea'){const key=detect(text);if(!key){add('assistant','I can help with three project families in this demo: plant watering, a room temperature/humidity monitor, and an automatic night light. Please choose one, or describe just one of those projects. Other electronics ideas will need a live AI backend or more templates.');}else{current.key=key;current.stage='budget';add('assistant',`Let’s plan a ${templates[key].title.toLowerCase()}.\n\nWhat’s your total component budget in INR? For example, ₹1,500. Prices in this demo are illustrative.`);}}
else if(current.stage==='budget'){const budget=parseBudget(text);if(!budget)add('assistant','Please enter a budget between ₹100 and ₹1,00,000, for example ₹1,500.');else{current.budget=budget;current.stage=current.level?'complete':'level';if(current.stage==='level')add('assistant',`Got it—${money(budget)}. How much electronics experience do you have: beginner or intermediate?`);else complete();}}
else if(current.stage==='level'){const level=parseLevel(text);if(!level)add('assistant','Choose beginner if this is one of your first builds, or intermediate if you already know basic wiring and coding.');else{current.level=level;current.stage='complete';complete();}}
else {if(/budget|cost|price/i.test(text)){const budget=parseBudget(text);if(budget){current.budget=budget;complete();}else{current.stage='budget';add('assistant','What should the new budget be? Enter an amount in INR.');}}else if(/experience|beginner|intermediate/i.test(text)){const level=parseLevel(text);if(level){current.level=level;complete();}else{current.stage='level';add('assistant','Would you like the beginner or intermediate plan?');}}else if(/component|material|parts|need/i.test(text)){activeTab='components';add('assistant','The Components tab lists quantities, selection notes and sample prices. Check exact part specifications before buying.');}else if(/reference|resource|tutorial|link/i.test(text)){activeTab='resources';add('assistant','Open the References tab for curated documentation and tutorials relevant to this plan.');}else if(/test|check/i.test(text)){activeTab='testing';add('assistant','The Test checklist tab includes the checks to work through as you build. These are suggested checks, not results from a simulation.');}else if(/step|work|build|explain/i.test(text)){activeTab='steps';add('assistant','The Build steps tab explains the sequence. Start by testing each subsystem before combining them.');}else add('assistant','Your plan is ready. I can show components, build steps, test checks or references, and change your budget or experience. Use New project to plan a different build. This curated demo cannot answer unrestricted technical follow-ups.');}
render();}
function complete(){const p=current.aiPlan||planFor(current.key,current.budget,current.level);activeTab='components';add('assistant',`Your ${p.level.toLowerCase()} project plan is ready.\n\nThe sample component total is ${money(p.total)}. ${p.over?`That is ${money(p.total-p.budget)} above your budget. I’ve kept the necessary supporting parts in the list; consider reusing parts or increasing the budget.`:`That leaves ${money(p.budget-p.total)} within your stated budget, before shipping and any additional tools.`}\n\nExplore the blueprint for components, build steps, test checks and references.`);}
function renderPlan(){const ready=current.stage==='complete'&&current.key&&current.budget&&current.level;$('planStatus').textContent=ready?'PLAN READY':current.key?'GATHERING REQUIREMENTS':'WAITING FOR YOUR IDEA';if(!ready){$('planContent').innerHTML=`<div class="empty-plan"><div class="blueprint-icon">▤</div><h2>${current.key?'A few details, then a plan.':'An idea is all you need.'}</h2><p>${current.key?'Tell me your budget and experience so I can prepare your project blueprint.':'Your components, build steps and resources will come together here.'}</p><div class="plan-placeholders"><span>Components</span><span>Build steps</span><span>References</span></div></div>`;return;}
const p=current.aiPlan||planFor(current.key,current.budget,current.level);$('planContent').innerHTML=`<div class="plan-body"><span class="plan-eyebrow">YOUR PROJECT BLUEPRINT</span><h2>${esc(p.title)}</h2><div class="plan-tags"><span>${esc(p.level)}</span><span>Low-voltage prototype</span><span>Budget ${money(p.budget)}</span></div><p>${esc(p.summary)}</p><div class="budget-box ${p.over?'over':''}"><span>${p.over?'Above your budget by '+money(p.total-p.budget):'Sample component estimate'}<br><small>Illustrative prices · excludes shipping / tools</small></span><strong>${money(p.total)}</strong></div><div class="plan-tabs" role="tablist" aria-label="Project plan sections">${[['components','Components'],['steps','Build steps'],['testing','Test checklist'],['resources','References']].map(([id,label])=>`<button role="tab" id="tab-${id}" aria-controls="planTabContent" aria-selected="${activeTab===id}" class="${activeTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div class="tab-content" id="planTabContent" role="tabpanel" aria-labelledby="tab-${activeTab}">${tabContent(p)}</div><div class="plan-actions"><button id="downloadPlan" class="button">↓ Download full plan</button><button id="downloadBom" class="button">↓ Component CSV</button></div><p class="plan-scope">An educational starting plan. AI output requires technical review. No circuit simulation, pin-by-pin wiring verification or automatic datasheet checks are performed.</p></div>`;}
function tabContent(p){if(activeTab==='components')return`<table><thead><tr><th>Component / selection note</th><th>Qty</th><th>Subtotal</th></tr></thead><tbody>${p.bom.map(r=>`<tr><td>${esc(r[0])}<small>${esc(r[3])}</small></td><td>${r[1]}</td><td>${money(r[1]*r[2])}</td></tr>`).join('')}</tbody></table><p class="bom-note">Already own a listed part? Reuse it if its exact specifications meet the requirements. The estimate assumes all items are purchased.</p>`;
if(activeTab==='steps')return`<div class="block-diagram">${p.blocks.map((b,i)=>`${i?'<i>→</i>':''}<span>${esc(b)}</span>`).join('')}</div><p class="bom-note">Conceptual signal flow, not a wiring diagram.</p>${p.steps.map(([title,text],i)=>`<article class="plan-step"><span>0${i+1}</span><div><strong>${esc(title)}</strong><p>${esc(text)}${p.level==='Beginner'&&i===0?' Work on this step alone before adding more parts.':''}</p></div></article>`).join('')}${p.level==='Intermediate'?`<p>${esc(p.advanced)}</p>`:''}`;
if(activeTab==='testing')return p.tests.map((t,i)=>`<article class="plan-step"><span>0${i+1}</span><div><p>${esc(t)}</p></div></article>`).join('');
return p.refs.map(([title,url,note])=>`<a class="resource" href="${url}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗<small>${esc(note)}</small></a>`).join('');}
function fullText(p){return`CIRCUITGUIDE — PROJECT PLAN\n${p.title}\nExperience: ${p.level}\nBudget: ${money(p.budget)}\nSample estimate: ${money(p.total)}\n${p.over?'OVER BUDGET: '+money(p.total-p.budget):'Within stated budget before shipping/tools'}\n\n${p.summary}\n\nCOMPONENTS\n${p.bom.map(r=>`${r[1]} × ${r[0]} — ${money(r[1]*r[2])}\n  ${r[3]}`).join('\n')}\n\nBUILD STEPS\n${p.steps.map(([a,b],i)=>`${i+1}. ${a}\n${b}`).join('\n\n')}\n${p.level==='Intermediate'?p.advanced:''}\n\nTEST CHECKLIST\n${p.tests.map(t=>'[ ] '+t).join('\n')}\n\nREFERENCES\n${p.refs.map(([a,b])=>a+'\n'+b).join('\n\n')}\n\nSCOPE\nAI or demo-generated plan. Approximate INR estimates, not live quotes. Educational starting plan; no complete schematic, simulation or automatic electrical validation. Verify exact parts, current ratings and wiring before physical assembly.`;}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared.');}
$('chatForm').addEventListener('submit',e=>{e.preventDefault();const text=$('messageInput').value;$('messageInput').value='';respond(text);});
$('messageInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('chatForm').requestSubmit();}});
$('quickReplies').addEventListener('click',e=>{const b=e.target.closest('[data-reply]');if(b)respond(b.dataset.reply);});
document.querySelector('.suggestions').addEventListener('click',e=>{const b=e.target.closest('[data-prompt]');if(!b)return;if(busy)return;if(current.key&&!confirm('Start this project? Your current conversation is kept in history.'))return;current=fresh();respond(b.dataset.prompt);$('messageInput').focus();});
$('newChat').addEventListener('click',()=>{cancelRequest();current=fresh();activeTab='components';render();$('messageInput').focus();});
$('history').addEventListener('click',e=>{const b=e.target.closest('[data-history]');if(b){const entry=history.find(x=>x.id===b.dataset.history);if(entry){cancelRequest();current=JSON.parse(JSON.stringify(entry));activeTab='components';render();}}});
$('planContent').addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;renderPlan();document.getElementById('tab-'+activeTab).focus();return;}const p=current.aiPlan||planFor(current.key,current.budget,current.level);if(!p)return;if(e.target.closest('#downloadPlan'))download(fullText(p),'text/plain;charset=utf-8','circuitguide-project-plan.txt');if(e.target.closest('#downloadBom')){const rows=[['Component','Quantity','Demo unit price INR','Subtotal INR','Selection note'],...p.bom.map(r=>[r[0],r[1],r[2],r[1]*r[2],r[3]])];download('\ufeff'+rows.map(r=>r.map(c=>'"'+String(/^[=+\-@\t\r]/.test(String(c))?"'"+c:c).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8','circuitguide-components.csv');}});
$('aboutButton').addEventListener('click',()=>$('aboutDialog').showModal());$('closeAbout').addEventListener('click',()=>$('aboutDialog').close());$('clearHistory').addEventListener('click',async()=>{if(!confirm(account?'Clear all projects saved to your account?':'Clear all CircuitGuide conversations in this browser?'))return;cancelRequest();try{if(account){await saveQueue;await api('/api/projects',{method:'DELETE',body:'{}'});savedVersions.clear();}history=[];current=fresh();render();$('aboutDialog').close();toast('Saved conversations cleared.');}catch(error){toast(error.message);}});
$('accountButton').addEventListener('click',async()=>{if(account){try{cancelRequest();await saveQueue;await api('/api/auth/logout',{method:'POST',body:'{}'});authGeneration++;savedVersions.clear();loadGuest();toast('Logged out. Your account projects remain saved.');}catch(error){toast(error.message);}return;}if(location.protocol==='file:'){toast('Run npm start and open http://localhost:4173 to log in.');return;}if(!authAvailable){toast('Restart the VS Code server: Ctrl+C, then npm start. Refresh this page to enable accounts.');return;}authMode='login';authView();$('authDialog').showModal();});
$('closeAuth').addEventListener('click',()=>$('authDialog').close());$('authSwitch').addEventListener('click',()=>{authMode=authMode==='login'?'register':'login';authView();});
$('authForm').addEventListener('submit',async e=>{e.preventDefault();$('authSubmit').disabled=true;$('authError').textContent='';try{const data=await api('/api/auth/'+authMode,{method:'POST',body:JSON.stringify({name:$('authName').value,email:$('authEmail').value,password:$('authPassword').value})});await loadAccount(data.user);$('authPassword').value='';$('authDialog').close();toast('Welcome, '+data.user.name+'. Your account workspace is ready.');}catch(error){$('authError').textContent=error.message;}finally{$('authSubmit').disabled=false;}});
function setBusy(value){busy=value;document.querySelector('#chatForm button').disabled=value;$('messageInput').disabled=value;document.querySelector('#chatForm button').textContent=value?'…':'↑';if(value)$('stageLabel').textContent='GROQ IS THINKING…';}
function cancelRequest(){requestController?.abort();requestController=null;setBusy(false);}
async function respond(input){
 if(!liveAI){if(current.key==='ai'){toast('Start the local server with a Groq key to continue this AI conversation.');return;}return demoRespond(input);}
 const text=input.trim();if(!text||busy)return;
 if(loginForAI&&!account){$('messageInput').value=text;authMode='login';authView();$('authDialog').showModal();toast('Log in to use the live AI assistant.');return;}
 add('user',text);current.key='ai';render();setBusy(true);
 const controller=new AbortController();requestController=controller;
 const conversationId=current.id;
 const timeout=setTimeout(()=>controller.abort(),70000);
 try{
 const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:current.messages.slice(-20).map(m=>({role:m.role,content:m.text})),planContext:current.aiPlan||null}),signal:controller.signal});
 const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed. Please retry.');
 if(current.id!==conversationId||controller.signal.aborted)return;
 add('assistant',data.reply);current.stage=data.stage;current.budget=data.budget;current.level=data.level;
 if(data.plan){current.aiPlan=data.plan;activeTab='components';}else if(data.stage!=='complete'){current.aiPlan=null;}
 render();
 }catch(error){if(current.id===conversationId&&requestController===controller){toast(error.name==='AbortError'?'Request timed out. Please try again.':error.message);$('messageInput').value=text;}}
 finally{clearTimeout(timeout);if(requestController===controller){requestController=null;setBusy(false);render();}}
}
async function connectBackend(){
 if(location.protocol==='file:'){setMode('FILE MODE · DEMO','Open http://localhost:4173 after running npm start to use Groq.');return;}
 try{const response=await fetch('/api/status');if(!response.ok)throw new Error();const status=await response.json();liveAI=status.configured;loginForAI=!!status.authenticationRequired;
 setMode(liveAI?'GROQ · LIVE AI':'GROQ · KEY NEEDED',liveAI?'Messages and current project context are sent to Groq. Costs are estimates; references are curated.':'Add your Groq key to .env and restart the server. Sample demo mode is available meanwhile.');
 if(liveAI&&current.messages.length===1){current.messages[0].text='Hi! I’m CircuitGuide, powered by Groq. Describe the electronics project you want to build. I’ll ask about your budget, experience and any missing requirements, then prepare your plan.';render();}
 }catch{setMode('OFFLINE DEMO','Backend unavailable. Start npm start, then open http://localhost:4173 for live AI.');}
}
function setMode(label,note){document.querySelector('.demo-tag').textContent=label;document.querySelector('form>small').textContent=note;accountUI();}
render();initAccount().finally(connectBackend);
